create extension if not exists pgcrypto;
create type public.app_role as enum ('owner','operator','client','staff','auditor');
create type public.approval_state as enum ('draft','needs_review','approved','rejected','published');
create type public.invoice_state as enum ('draft','open','paid','void','overdue');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,created_at timestamptz not null default now());
create table public.memberships(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,user_id uuid not null references auth.users on delete cascade,role public.app_role not null,created_at timestamptz not null default now(),unique(organization_id,user_id));
create table public.client_projects(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,name text not null,public_summary text not null default '',approval_status public.approval_state not null default 'draft',deduplication_key text not null,approved_by uuid references auth.users,approved_at timestamptz,published_at timestamptz,created_at timestamptz not null default now(),unique(organization_id,deduplication_key));
create table public.cost_items(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete cascade,project_id uuid references public.client_projects on delete set null,category text not null check(category in ('tool','subscription','staff','service','adjustment')),client_label text not null,client_amount_minor bigint not null check(client_amount_minor>=0),currency text not null default 'PHP',recurring_interval text check(recurring_interval in ('one_time','weekly','monthly','quarterly','annual')),active boolean not null default true,internal_cost_minor bigint,internal_margin_minor bigint generated always as (client_amount_minor-coalesce(internal_cost_minor,0)) stored,created_at timestamptz not null default now());
create table public.wallets(id uuid primary key default gen_random_uuid(),organization_id uuid unique not null references public.organizations on delete cascade,currency text not null default 'PHP',balance_minor bigint not null default 0 check(balance_minor>=0),updated_at timestamptz not null default now());
create table public.wallet_ledger(id uuid primary key default gen_random_uuid(),wallet_id uuid not null references public.wallets on delete restrict,amount_minor bigint not null,kind text not null check(kind in ('credit','debit','refund','adjustment')),reference_type text not null,reference_id text not null,idempotency_key text unique not null,created_at timestamptz not null default now());
create table public.invoices(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations on delete restrict,number text unique not null,status public.invoice_state not null default 'draft',currency text not null default 'PHP',subtotal_minor bigint not null default 0,total_minor bigint not null default 0,due_at timestamptz,paid_at timestamptz,stripe_customer_id text,stripe_invoice_id text unique,created_at timestamptz not null default now());
create table public.audit_events(id bigint generated always as identity primary key,organization_id uuid references public.organizations on delete set null,actor_id uuid references auth.users on delete set null,action text not null,entity_type text not null,entity_id text not null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create or replace function public.is_member(org uuid,allowed public.app_role[]) returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.memberships m where m.organization_id=org and m.user_id=auth.uid() and m.role=any(allowed))$$;
alter table public.organizations enable row level security; alter table public.memberships enable row level security; alter table public.client_projects enable row level security; alter table public.cost_items enable row level security; alter table public.wallets enable row level security; alter table public.wallet_ledger enable row level security; alter table public.invoices enable row level security; alter table public.audit_events enable row level security;
create policy org_read on public.organizations for select using(public.is_member(id,array['owner','operator','client','staff','auditor']::public.app_role[]));
create policy project_read on public.client_projects for select using(public.is_member(organization_id,array['owner','operator','client','staff','auditor']::public.app_role[]));
create policy project_internal_write on public.client_projects for all using(public.is_member(organization_id,array['owner','operator']::public.app_role[])) with check(public.is_member(organization_id,array['owner','operator']::public.app_role[]));
create policy cost_client_read on public.cost_items for select using(public.is_member(organization_id,array['owner','operator','client','auditor']::public.app_role[]) and (not public.is_member(organization_id,array['client']::public.app_role[]) or internal_cost_minor is null));
create policy cost_internal_write on public.cost_items for all using(public.is_member(organization_id,array['owner','operator']::public.app_role[])) with check(public.is_member(organization_id,array['owner','operator']::public.app_role[]));
create policy wallet_read on public.wallets for select using(public.is_member(organization_id,array['owner','operator','client','auditor']::public.app_role[]));
create policy invoice_read on public.invoices for select using(public.is_member(organization_id,array['owner','operator','client','auditor']::public.app_role[]));
create policy audit_internal_read on public.audit_events for select using(public.is_member(organization_id,array['owner','operator','auditor']::public.app_role[]));
revoke all on public.cost_items from anon,authenticated; grant select(client_label,client_amount_minor,currency,recurring_interval,active,organization_id,project_id,id,category,created_at) on public.cost_items to authenticated; grant all on public.cost_items to service_role;